114	
115	      var del = document.createElement('button');
116	      del.type = 'button';
117	      del.className = 'delete';
118	      del.setAttribute('data-testid', 'todo-delete');
119	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
120	      del.textContent = 'Delete';
121	      del.addEventListener('click', function () {
122	        removeTodo(todo.id);
123	      });
124	
125	      li.appendChild(text);
126	      li.appendChild(del);
127	      list.appendChild(li);
128	    });
129	    empty.hidden = todos.length > 0;
130	  }
131	
132	  function addTodo(text) {
133	    todos.push({ id: newId(), text: text, createdAt: Date.now() });
134	    save();
135	    render();
136	  }
137	
